using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Define the data path
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");

        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found at: " + dataPath);
            return;
        }

        // 2. Read and update the JSON data file
        string jsonData = File.ReadAllText(dataPath);
        JArray dataArray = JArray.Parse(jsonData);
        bool studentFound = false;
        int studentIndex = -1;

        for (int i = 0; i < dataArray.Count; i++)
        {
            if (dataArray[i]["student_id"] != null && dataArray[i]["student_id"].ToString() == "S003")
            {
                dataArray[i]["science_score"] = 92;
                studentIndex = i;
                studentFound = true;
                break;
            }
        }

        if (studentFound)
        {
            // Save the updated JSON back to the file
            File.WriteAllText(dataPath, dataArray.ToString());
            Debug.Log("Updated S003 science score to 92 in JSON.");
        }
        else
        {
            Debug.LogError("Student S003 not found in data.");
            return;
        }

        // 3. Update the chart in the scene
        GameObject chartObj = GameObject.Find("ScienceScoreChart");
        if (chartObj != null)
        {
            BarChart chart = chartObj.GetComponent<BarChart>();
            if (chart != null)
            {
                // We assume the chart data index matches the JSON index or we find it by X-axis label
                var xAxis = chart.GetOrAddChartComponent<XAxis>();
                int chartDataIndex = -1;

                // Try to find the index by checking the X-axis labels (student IDs)
                for (int i = 0; i < xAxis.data.Count; i++)
                {
                    if (xAxis.data[i] == "S003")
                    {
                        chartDataIndex = i;
                        break;
                    }
                }

                // If not found in labels, fallback to the index from the JSON array
                if (chartDataIndex == -1)
                {
                    chartDataIndex = studentIndex;
                }

                // Update the first serie (Science Scores) at the found index
                chart.UpdateData(0, chartDataIndex, 92.00f);

                // Refresh the chart to show changes
                chart.RefreshChart();
                Debug.Log("ScienceScoreChart updated successfully for S003.");
            }
            else
            {
                Debug.LogError("BarChart component not found on ScienceScoreChart.");
            }
        }
        else
        {
            Debug.LogError("ScienceScoreChart GameObject not found in the scene.");
        }
    }
}

