using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Define parameters
        string chartName = "ElectricityChart_Building002";
        string targetTime = "12:00";
        float newValue = 450.00f;
        string relativePath = "city/building_002.json";
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData", relativePath);

        // 2. Update the JSON data file to persist the change
        if (File.Exists(dataPath))
        {
            try
            {
                string jsonData = File.ReadAllText(dataPath);
                JArray data = JArray.Parse(jsonData);
                bool dataUpdated = false;

                foreach (var item in data)
                {
                    if (item["time"] != null && item["time"].ToString() == targetTime)
                    {
                        item["electricity"] = newValue;
                        dataUpdated = true;
                        break;
                    }
                }

                if (dataUpdated)
                {
                    File.WriteAllText(dataPath, data.ToString());
                    Debug.Log("Successfully updated electricity data in JSON for 12:00.");
                }
            }
            catch (System.Exception e)
            {
                Debug.LogError("Failed to update JSON file: " + e.Message);
            }
        }

        // 3. Update the visual chart in the virtual environment
        GameObject chartObj = GameObject.Find(chartName);
        if (chartObj != null)
        {
            // XCharts uses BaseChart as the base class for BarChart, LineChart, etc.
            BaseChart chart = chartObj.GetComponent<BaseChart>();
            if (chart != null)
            {
                XAxis xAxis = chart.GetChartComponent<XAxis>();
                if (xAxis != null)
                {
                    // Find the index of the category "12:00" in the X-Axis
                    int dataIndex = xAxis.data.IndexOf(targetTime);

                    if (dataIndex != -1)
                    {
                        // Update the first series (index 0) at the found data index
                        // We cast to double as XCharts UpdateData accepts double
                        chart.UpdateData(0, dataIndex, (double)newValue);
                        Debug.Log("Successfully updated chart visualization for 12:00.");
                    }
                    else
                    {
                        Debug.LogWarning("Time '12:00' not found in the chart's X-Axis data.");
                    }
                }
            }
            else
            {
                Debug.LogError("BaseChart component not found on " + chartName);
            }
        }
        else
        {
            Debug.LogError("Target chart object '" + chartName + "' not found in the scene.");
        }
    }
}

