using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Load data from StreamingAssets
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");
        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found: " + dataPath);
            return;
        }
        string jsonData = File.ReadAllText(dataPath);
        JArray data = JArray.Parse(jsonData);

        // 2. Create the Chart GameObject and Canvas
        string viewId = "StudentScoresChart";
        GameObject chartObj = new GameObject(viewId);

        // Set up Canvas for World Space rendering
        Canvas canvas = chartObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        chartObj.AddComponent<CanvasScaler>();
        chartObj.AddComponent<GraphicRaycaster>();

        // 3. Add and configure the BarChart component
        BarChart chart = chartObj.AddComponent<BarChart>();
        chart.Init();

        // Set Chart Title
        var title = chart.GetOrAddChartComponent<Title>();
        title.text = "Student Scores Analysis";
        title.subText = "Math, Science, and English";

        // Configure Legend
        var legend = chart.GetOrAddChartComponent<Legend>();
        legend.show = true;

        // Configure Axes
        var xAxis = chart.GetOrAddChartComponent<XAxis>();
        xAxis.type = Axis.AxisType.Category;

        var yAxis = chart.GetOrAddChartComponent<YAxis>();
        yAxis.type = Axis.AxisType.Value;

        // 4. Add Series for Math, Science, and English
        chart.RemoveData();
        var mathSerie = chart.AddSerie<Bar>("Math Score");
        var scienceSerie = chart.AddSerie<Bar>("Science Score");
        var englishSerie = chart.AddSerie<Bar>("English Score");

        // Set colors for series
        mathSerie.itemStyle.color = "#5470C6FF";
        scienceSerie.itemStyle.color = "#91CC75FF";
        englishSerie.itemStyle.color = "#FAC858FF";

        // 5. Populate data into the chart
        foreach (var item in data)
        {
            string studentName = item["name"].ToString();
            float mathScore = (float)item["math_score"];
            float scienceScore = (float)item["science_score"];
            float englishScore = (float)item["english_score"];

            chart.AddXAxisData(studentName);
            chart.AddData(0, mathScore);
            chart.AddData(1, scienceScore);
            chart.AddData(2, englishScore);
        }

        // 6. Position and Scale the chart
        // TeacherDesk position (top center): (0.0, 0.92, -2.3)
        // TeacherDesk size: (1.8, 0.92, 0.8)
        // Place the chart slightly above the desk surface
        Vector3 deskTopCenter = new Vector3(0.00f, 0.92f, -2.30f);
        chartObj.transform.position = deskTopCenter + new Vector3(0.00f, 0.05f, 0.00f);

        // Default orientation: face towards the user
        // User is at (0, 1.7, 0), Desk is at (0, 0.92, -2.3). 
        // The chart should face the +Z direction to look at the user.
