            title.text = studentName + " (" + studentId + ")";
            title.subText = "Subject Scores";

            // Configure Legend
            var legend = chart.GetOrAddChartComponent<Legend>();
            legend.show = true;

            // Configure Axes
            var xAxis = chart.GetOrAddChartComponent<XAxis>();
            xAxis.type = Axis.AxisType.Category;

            var yAxis = chart.GetOrAddChartComponent<YAxis>();
            yAxis.type = Axis.AxisType.Value;
            yAxis.minMaxType = Axis.AxisMinMaxType.Custom;
            yAxis.min = 0f;
            yAxis.max = 100f;

            // Add Data
            chart.RemoveData();
            chart.AddXAxisData("Math");
            chart.AddXAxisData("Science");
            chart.AddXAxisData("English");

            var serie = chart.AddSerie<Bar>("Scores");
            serie.itemStyle.color = "#5470C6FF"; // Default blue

            chart.AddData(0, mathScore);
            chart.AddData(0, scienceScore);
            chart.AddData(0, englishScore);

            // 4. Position and Rotate the chart
            // Position in a row: move right for each index
            chartObj.transform.position = leftStart + new Vector3(-i * spacing, 0f, 0f);

            // Scale down the UI to world units (1 unit = 1 meter)
            chartObj.transform.localScale = new Vector3(0.002f, 0.002f, 0.002f);

            // Rotate to face the user (User is at Z=0 looking at -Z, so charts face +Z)
            chartObj.transform.rotation = Quaternion.LookRotation(new Vector3(0f, 0f, 1f));
