using Newtonsoft.Json.Linq;
using XCharts.Runtime;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Find the existing chart GameObject in the scene
        GameObject chartObj = GameObject.Find("MathScoreChart");
        if (chartObj == null)
        {
            Debug.LogError("MathScoreChart not found in the scene graph.");
            return;
        }

        // 2. Get the BarChart component
        BarChart chart = chartObj.GetComponent<BarChart>();
        if (chart == null)
        {
            Debug.LogError("BarChart component not found on MathScoreChart.");
            return;
        }

        // 3. Identify the index for student "S002"
        // We assume the X-axis data contains the student IDs as labels
        XAxis xAxis = chart.GetChartComponent<XAxis>();
        int studentIndex = -1;
        for (int i = 0; i < xAxis.data.Count; i++)
        {
            if (xAxis.data[i] == "S002")
            {
                studentIndex = i;
                break;
            }
        }

        // 4. Update the score and apply highlight if the student is found
        if (studentIndex != -1)
        {
            // Update the math score value to 85.00f in the first series (index 0)
            chart.UpdateData(0, studentIndex, 85.00f);

            // Access the series to modify the visual style of the specific data point
            var serie = chart.GetSerie(0);
            if (serie != null && studentIndex < serie.dataCount)
            {
                // Enable custom item style for this specific bar to highlight it
                serie.data[studentIndex].itemStyle.enable = true;

                // Set the highlight color to a distinct Red (#FF0000FF)
                Color highlightColor;
                if (ColorUtility.TryParseHtmlString("#FF0000FF", out highlightColor))
                {
                    serie.data[studentIndex].itemStyle.color = highlightColor;
                }

                // Refresh the chart to ensure the visual changes are rendered immediately
                chart.RefreshChart();

                Debug.Log("Successfully updated student S002 math score to 85.00 and highlighted the bar.");
            }
        }
        else
        {
            Debug.LogWarning("Student S002 was not found in the MathScoreChart data labels.");
        }
    }
}

