using Newtonsoft.Json.Linq;
using XCharts.Runtime;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Define data and spec paths
        // The data file is city/building_003.json
        string dataRelativePath = "city/building_003.json";
        string specRelativePath = "city/building_003_scatter3d_spec.json";
        string fullSpecPath = Path.Combine(Application.streamingAssetsPath, "DxRData", specRelativePath);

        // 2. Create the JSON specification for the 3D scatter plot
        // We use 'time' for X, 'gas' for Y, and 'electricity' for Z to create a 3D visualization.
        JObject spec = new JObject();
        spec["data"] = dataRelativePath;
        spec["mark"] = "point";

        JObject encoding = new JObject();

        // X-axis: Time (Nominal/Ordinal)
        encoding["x"] = new JObject { ["field"] = "time", ["type"] = "nominal" };

        // Y-axis: Gas usage (Quantitative)
        encoding["y"] = new JObject { ["field"] = "gas", ["type"] = "quantitative" };

        // Z-axis: Electricity usage (Quantitative)
        encoding["z"] = new JObject { ["field"] = "electricity", ["type"] = "quantitative" };

        // Color: Cyan
        encoding["color"] = new JObject { ["value"] = "#00FFFFFF" };

        // Size of points
        encoding["size"] = new JObject { ["value"] = 0.05f };

        spec["encoding"] = encoding;

        // Ensure directory exists and write the spec file
        FileInfo specFile = new FileInfo(fullSpecPath);
        if (!specFile.Directory.Exists) specFile.Directory.Create();
        File.WriteAllText(fullSpecPath, spec.ToString());

        // 3. Create the Visualization GameObject
        GameObject chartObj = new GameObject("Building003GasUsage3DScatter");

        // Add DxR Vis component
        Vis vis = chartObj.AddComponent<Vis>();
        vis.dataURL = dataRelativePath;
        vis.specsURL = specRelativePath;

        // 4. Calculate Placement
        // Since the scene graph is empty, we assume a default building position in front of the user.
        // User is at (0, 1.7, 0) looking at (0, 0, -1).
        // We place the "building" at (0, 0, -4) and the chart "above" it.
        Vector3 buildingPos = new Vector3(0f, 0f, -4.00f);
        float buildingHeight = 2.00f; 
        Vector3 chartPos = new Vector3(buildingPos.x, buildingPos.y + buildingHeight + 1.00f, buildingPos.z);

        chartObj.transform.position = chartPos;

        // 5. Scale the object
        // User requested "scale it to 2 times"
        chartObj.transform.localScale = new Vector3(2.00f, 2.00f, 2.00f);

        // 6. Orient to user
        // "orient it to me" - make the chart face the user's position
        Vector3 userPos = new Vector3(0f, 1.70f, 0f);
        chartObj.transform.LookAt(userPos);
        chartObj.transform.Rotate(0, 180, 0); // Flip to face user correctly as LookAt points the forward vector

        // 7. Initialize/Update the visualization
        vis.UpdateVis();
    }
}

