    private static void CreateElectricityChart(string filePath, string objName, string title, string hexColor, float angleOffset)
    {
        if (!File.Exists(filePath)) return;

        string jsonData = File.ReadAllText(filePath);
        JArray data = JArray.Parse(jsonData);

        // Create GameObject and Canvas
        GameObject chartObj = new GameObject(objName);
