        chartObj.transform.localScale = new Vector3(0.002f, 0.002f, 0.002f);

        // Add Bar Chart component
        BarChart chart = chartObj.AddComponent<BarChart>();

        // Configure Title
        var titleComp = chart.GetOrAddChartComponent<Title>();
        titleComp.text = title;
        titleComp.subText = "Electricity Usage";

        // Configure Axis
        chart.GetOrAddChartComponent<XAxis>().type = Axis.AxisType.Category;
        chart.GetOrAddChartComponent<YAxis>().type = Axis.AxisType.Value;

        // Add Data and Set Color
        var serie = chart.AddSerie<Bar>("Electricity");

        // Parse color
        Color barColor;
        if (!ColorUtility.TryParseHtmlString(hexColor, out barColor))
        {
            barColor = Color.white;
        }
        serie.itemStyle.color = barColor;

        // Fill data (limiting to first 20 entries for clarity if data is large)
        int count = 0;
        foreach (var item in data)
        {
            if (count > 20) break; 
            chart.AddXAxisData(item["time"].ToString());
            chart.AddData(0, (float)item["electricity"]);
            count++;
        }

        // Positioning in an arc relative to user
        // User is at (0, 1.7, 0) looking at (0, 0, -1)
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);
        Vector3 forward = new Vector3(0.00f, 0.00f, -1.00f);
        float radius = 2.00f;

        // Calculate position based on angle offset from the forward vector
        Quaternion rotation = Quaternion.Euler(0, angleOffset, 0);
        Vector3 direction = rotation * forward;
        Vector3 targetPos = userPos + direction * radius;
        targetPos.y = 1.40f; // Set height to slightly below eye level

        chartObj.transform.position = targetPos;

        // Make chart face the user
        chartObj.transform.LookAt(new Vector3(userPos.x, targetPos.y, userPos.z));
        chartObj.transform.Rotate(0, 180, 0); // Correct UI orientation
    }
}

