using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        // Define user position for orientation
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);

        // Data file paths
        string dataPath1 = Path.Combine(Application.streamingAssetsPath, "DxRData/city/building_001.json");
        string dataPath2 = Path.Combine(Application.streamingAssetsPath, "DxRData/city/building_002.json");

        // Create chart for Building 001
        Create3DBarChart(dataPath1, "Building001_ElectricityChart", new Vector3(2.00f, 1.50f, -3.80f), userPos);

        // Create chart for Building 002
        Create3DBarChart(dataPath2, "Building002_ElectricityChart", new Vector3(-2.00f, 1.50f, -3.80f), userPos);
    }

    private static void Create3DBarChart(string filePath, string viewId, Vector3 position, Vector3 userPos)
    {
        if (!File.Exists(filePath)) return;

        string jsonData = File.ReadAllText(filePath);
        JArray data = JArray.Parse(jsonData);

        // Create container object
        GameObject chartContainer = new GameObject(viewId);
        chartContainer.transform.position = position;

        // Chart parameters
        float chartWidth = 1.50f;
        float maxBarHeight = 1.00f;
        float barSpacing = chartWidth / data.Count;
        float barWidth = barSpacing * 0.80f;
        float maxElectricity = 2400.00f; // Based on data range provided

        Color barColor;
        ColorUtility.TryParseHtmlString("#0000FFFF", out barColor);

        // Create a base for the chart
        GameObject basePlate = GameObject.CreatePrimitive(PrimitiveType.Cube);
        basePlate.name = "Base";
        basePlate.transform.SetParent(chartContainer.transform);
        basePlate.transform.localPosition = new Vector3(0f, -0.05f, 0f);
        basePlate.transform.localScale = new Vector3(chartWidth + 0.1f, 0.05f, 0.2f);
        basePlate.GetComponent<Renderer>().material.color = Color.gray;

        // Generate bars
        for (int i = 0; i < data.Count; i++)
        {
            float electricity = data[i]["electricity"].Value<float>();
            float normalizedHeight = (electricity / maxElectricity) * maxBarHeight;

            GameObject bar = GameObject.CreatePrimitive(PrimitiveType.Cube);
            bar.name = "Bar_" + i;
            bar.transform.SetParent(chartContainer.transform);

            // Position bars from left to right
            float xPos = - (chartWidth / 2f) + (i * barSpacing) + (barSpacing / 2f);
            bar.transform.localPosition = new Vector3(xPos, normalizedHeight / 2f, 0f);
            bar.transform.localScale = new Vector3(barWidth, normalizedHeight, barWidth);

            // Set color to blue
            Renderer renderer = bar.GetComponent<Renderer>();
            renderer.material.color = barColor;
        }

        // Add a title label using a World Space Canvas
        GameObject canvasObj = new GameObject("TitleCanvas");
        canvasObj.transform.SetParent(chartContainer.transform);
        canvasObj.transform.localPosition = new Vector3(0f, maxBarHeight + 0.2f, 0f);

        Canvas canvas = canvasObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        RectTransform rect = canvas.GetComponent<RectTransform>();
        rect.sizeDelta = new Vector2(200f, 50f);
        canvasObj.transform.localScale = new Vector3(0.005f, 0.005f, 0.005f);

        GameObject textObj = new GameObject("TitleText");
        textObj.transform.SetParent(canvasObj.transform);
        Text titleText = textObj.AddComponent<Text>();
        titleText.text = viewId.Replace("_", " ");
        titleText.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
        titleText.fontSize = 24;
        titleText.alignment = TextAnchor.MiddleCenter;
        titleText.color = Color.white;
        textObj.GetComponent<RectTransform>().sizeDelta = new Vector2(200f, 50f);
        textObj.transform.localPosition = Vector3.zero;

        // Orient the chart to face the user
        Vector3 directionToUser = userPos - chartContainer.transform.position;
        directionToUser.y = 0; // Keep it upright
        if (directionToUser != Vector3.zero)
        {
            chartContainer.transform.rotation = Quaternion.LookRotation(directionToUser);
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Load and parse the student score data
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");
        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found: " + dataPath);
            return;
        }
        string jsonData = File.ReadAllText(dataPath);
        JArray dataArray = JArray.Parse(jsonData);

        // 2. Define shelf positions from the scene graph
        // ItemA: (-2.0, 0.5, -1.0), ItemB: (0.0, 0.5, -1.0), ItemC: (2.0, 0.5, -1.0)
        Vector3[] shelfPositions = new Vector3[] {
            new Vector3(-2.00f, 0.50f, -1.00f),
            new Vector3(0.00f, 0.50f, -1.00f),
            new Vector3(2.00f, 0.50f, -1.00f)
        };

        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);

        // 3. Create a chart for each of the first 3 students
        int count = Mathf.Min(dataArray.Count, shelfPositions.Length);
        for (int i = 0; i < count; i++)
        {
            JToken student = dataArray[i];
            string studentId = student["student_id"].ToString();
            string studentName = student["name"].ToString();
            float mathScore = (float)student["math_score"];
            float scienceScore = (float)student["science_score"];
            float englishScore = (float)student["english_score"];

            // Create Chart GameObject
            string viewId = "StudentScore_" + studentId;
            GameObject chartObj = new GameObject(viewId);

            // Set up World Space Canvas
            Canvas canvas = chartObj.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;
            chartObj.AddComponent<CanvasScaler>();
            chartObj.AddComponent<GraphicRaycaster>();

            // Add Bar Chart component
            BarChart chart = chartObj.AddComponent<BarChart>();
            chart.Init();
            chart.EnsureChartComponent<Title>().text = studentName;
            chart.EnsureChartComponent<Title>().subText = "Scores Analysis";

            // Configure Axes
            var xAxis = chart.EnsureChartComponent<XAxis>();
            xAxis.type = Axis.AxisType.Category;
            xAxis.show = true;

            var yAxis = chart.EnsureChartComponent<YAxis>();
            yAxis.type = Axis.AxisType.Value;
            yAxis.minMaxType = Axis.AxisMinMaxType.Custom;
            yAxis.min = 0f;
            yAxis.max = 100f;
            yAxis.show = true;

            // Add Data
            chart.RemoveData();
            chart.AddXAxisData("Math");
            chart.AddXAxisData("Science");
            chart.AddXAxisData("English");

            var serie = chart.AddSerie<Bar>("Scores");
            serie.itemStyle.color = i == 0 ? "#5470C6FF" : (i == 1 ? "#91CC75FF" : "#EE6666FF");

            chart.AddData(0, mathScore);
            chart.AddData(0, scienceScore);
            chart.AddData(0, englishScore);

            // 4. Position and Rotate the chart
            // Place 0.4m above the shelf top anchor
            chartObj.transform.position = shelfPositions[i] + new Vector3(0f, 0.40f, 0f);

            // Scale for world space visibility (XCharts are pixel-based, so we scale down)
            chartObj.transform.localScale = new Vector3(0.0015f, 0.0015f, 0.0015f);

            // Rotate to face the user
            Vector3 directionToUser = (userPos - chartObj.transform.position).normalized;
            directionToUser.y = 0; // Keep chart vertical
            chartObj.transform.rotation = Quaternion.LookRotation(directionToUser);

            // Adjust chart size in pixels
            chart.GetComponent<RectTransform>().sizeDelta = new Vector2(500f, 400f);
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Load and Update Data
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");
        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found: " + dataPath);
            return;
        }

        string jsonData = File.ReadAllText(dataPath);
        JArray dataArray = JArray.Parse(jsonData);

        // Update specific student scores as requested
        foreach (var item in dataArray)
        {
            string studentId = item["student_id"].ToString();
            if (studentId == "S003")
            {
                item["math_score"] = 91;
            }
            else if (studentId == "S005")
            {
                item["math_score"] = 67;
            }
        }

        // 2. Create Chart GameObject and Canvas
        GameObject chartObj = new GameObject("MathScoresAnalysisChart");
        // Position the chart in front of the user (User is at 0, 1.7, 0 looking at 0, 0, -1)
        chartObj.transform.position = new Vector3(0.00f, 1.50f, -2.50f);
        chartObj.transform.rotation = Quaternion.LookRotation(new Vector3(0, 0, -1)); // Face the user

        Canvas canvas = chartObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        chartObj.AddComponent<CanvasScaler>();
        chartObj.AddComponent<GraphicRaycaster>();

        // Adjust size for world space visibility
        RectTransform rectTransform = chartObj.GetComponent<RectTransform>();
        rectTransform.sizeDelta = new Vector2(600f, 400f);
        chartObj.transform.localScale = new Vector3(0.002f, 0.002f, 0.002f);

        // 3. Setup Bar Chart
        BarChart chart = chartObj.AddComponent<BarChart>();

        // Set Title
        var title = chart.GetOrAddChartComponent<Title>();
        title.text = "Math Scores Analysis";
        title.subText = "Updated Scores for S003 and S005";

        // Setup Axis
        chart.GetOrAddChartComponent<XAxis>().type = Axis.AxisType.Category;
        chart.GetOrAddChartComponent<YAxis>().type = Axis.AxisType.Value;
        chart.GetOrAddChartComponent<Legend>().show = true;

        // 4. Add Data and Set Color
        chart.RemoveData();
        var mathSerie = chart.AddSerie<Bar>("Math Score");

        // Set series color to dark blue
        Color darkBlue;
        if (ColorUtility.TryParseHtmlString("#00008BFF", out darkBlue))
        {
            mathSerie.itemStyle.color = darkBlue;
        }

        foreach (var item in dataArray)
        {
            string studentId = item["student_id"].ToString();
            float mathScore = (float)item["math_score"];

            chart.AddXAxisData(studentId);
            chart.AddData(0, mathScore);
        }
    }
}
